import{_ as t,o,c as s,ag as n}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"DSP Platform — Payments, Payouts & Business Rules (Client Handover)","description":"","frontmatter":{},"headers":[],"relativePath":"CLIENT_HANDOVER_STRIPE_PAYMENTS_AND_RULES.md","filePath":"CLIENT_HANDOVER_STRIPE_PAYMENTS_AND_RULES.md"}'),r={name:"CLIENT_HANDOVER_STRIPE_PAYMENTS_AND_RULES.md"};function a(d,e,i,l,h,c){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="dsp-platform-—-payments-payouts-business-rules-client-handover" tabindex="-1">DSP Platform — Payments, Payouts &amp; Business Rules (Client Handover) <a class="header-anchor" href="#dsp-platform-—-payments-payouts-business-rules-client-handover" aria-label="Permalink to &quot;DSP Platform — Payments, Payouts &amp; Business Rules (Client Handover)&quot;">​</a></h1><p>This document explains everything you need to know about how payments, payouts, refunds, and lesson status work on the platform. It is written for the client (Switzerland) and covers Stripe sandbox testing, edge cases we handle, and the rules enforced in code.</p><hr><h2 id="_1-currency-and-checkout" tabindex="-1">1. Currency and checkout <a class="header-anchor" href="#_1-currency-and-checkout" aria-label="Permalink to &quot;1. Currency and checkout&quot;">​</a></h2><ul><li><strong>All prices and payments are in CHF (Swiss Francs).</strong></li><li>Stripe Checkout is configured to show <strong>only CHF</strong> (no automatic conversion to the customer’s local currency). If you ever see another currency (e.g. PKR) on the Stripe payment page, disable <strong>Adaptive Pricing</strong> in Stripe Dashboard: <strong>Settings → Adaptive Pricing</strong> → turn off for Checkout.</li><li><strong>Lesson times</strong> (e.g. “3 PM–4 PM”) are interpreted in <strong>Switzerland time</strong> (Europe/Zurich). So “mark as completed” and “lesson ended” checks use Swiss time correctly for students and instructors in any country.</li></ul><hr><h2 id="_2-when-does-the-instructor-get-paid-payout-flow" tabindex="-1">2. When does the instructor get paid? (Payout flow) <a class="header-anchor" href="#_2-when-does-the-instructor-get-paid-payout-flow" aria-label="Permalink to &quot;2. When does the instructor get paid? (Payout flow)&quot;">​</a></h2><h3 id="step-1-lesson-is-marked-completed" tabindex="-1">Step 1: Lesson is marked completed <a class="header-anchor" href="#step-1-lesson-is-marked-completed" aria-label="Permalink to &quot;Step 1: Lesson is marked completed&quot;">​</a></h3><ul><li>The <strong>instructor</strong> (or admin) marks the lesson as <strong>Completed</strong> in the platform <strong>after</strong> the lesson end time. The system does <strong>not</strong> allow marking as completed before the slot end time (see <a href="#6-lesson-completed--missed-status">§6</a>).</li><li>For <strong>paid</strong> lessons, as soon as the lesson is marked completed, the slot becomes <strong>eligible for payout</strong> after a short delay (currently <strong>1 minute</strong> in the configuration; this can be increased to e.g. 3 days for production).</li></ul><h3 id="step-2-payout-job-runs" tabindex="-1">Step 2: Payout job runs <a class="header-anchor" href="#step-2-payout-job-runs" aria-label="Permalink to &quot;Step 2: Payout job runs&quot;">​</a></h3><ul><li>A <strong>payout job</strong> runs on the server every <strong>3 minutes</strong>. It finds all slots that: <ul><li>are marked <strong>completed</strong>,</li><li>are <strong>paid</strong>,</li><li>have passed the “payout eligible” time,</li><li>and have not been paid out yet.</li></ul></li><li>For each such slot it creates a <strong>manual payout</strong> from the instructor’s Stripe Connect balance to their bank. Each lesson is paid out <strong>only once</strong> (no double payouts; the code prevents race conditions).</li></ul><h3 id="step-3-when-does-the-money-appear-in-stripe-bank" tabindex="-1">Step 3: When does the money appear in Stripe / bank? <a class="header-anchor" href="#step-3-when-does-the-money-appear-in-stripe-bank" aria-label="Permalink to &quot;Step 3: When does the money appear in Stripe / bank?&quot;">​</a></h3><ul><li><strong>In Stripe (Connect account):</strong> After a student pays, the instructor’s share appears in their Stripe Connect balance. It is first <strong>“Available soon”</strong> (pending).</li><li><strong>When it becomes “Available to pay out” (Switzerland, CH):</strong><ul><li><strong>First payout ever</strong> for that instructor: Stripe’s <strong>initial settlement</strong> is typically <strong>7 calendar days</strong>. So the first time an instructor receives funds, they usually become available for payout <strong>7–14 days</strong> after the first successful payment.</li><li><strong>After the first payout:</strong> <strong>3 business days</strong> (Mon–Fri, excluding holidays). So a Monday charge is typically available on Thursday.</li></ul></li><li><strong>When we actually send it to the bank:</strong> As soon as the funds are “Available to pay out” in Stripe and our payout job has run (every 3 minutes), we create the payout to the instructor’s bank. The exact arrival time in the bank depends on Stripe and the bank (often 1–2 business days).</li></ul><p><strong>Summary for the client:</strong><br> “After the instructor marks the lesson completed, our system will send their share to their bank the next time the payout job runs (every 3 minutes), but only once Stripe has made those funds ‘available’ (first time: about 7 days; afterwards: about 3 business days).”</p><hr><h2 id="_3-stripe-test-cards-sandbox" tabindex="-1">3. Stripe test cards (sandbox) <a class="header-anchor" href="#_3-stripe-test-cards-sandbox" aria-label="Permalink to &quot;3. Stripe test cards (sandbox)&quot;">​</a></h2><p>You are using a <strong>Stripe sandbox (test)</strong> account. No real money moves. Use <strong>test API keys</strong> and the test cards below in your app and in the Stripe Dashboard when testing.</p><h3 id="successful-payment-no-3ds" tabindex="-1">Successful payment (no 3DS) <a class="header-anchor" href="#successful-payment-no-3ds" aria-label="Permalink to &quot;Successful payment (no 3DS)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Brand</th><th>Card number</th><th>CVC</th><th>Expiry</th></tr></thead><tbody><tr><td>Visa</td><td>4242 4242 4242 4242</td><td>Any 3 digits</td><td>Any future date (e.g. 12/34)</td></tr><tr><td>Mastercard</td><td>5555 5555 5555 4444</td><td>Any 3 digits</td><td>Any future date</td></tr><tr><td>Switzerland (CH)</td><td>4000 0075 6000 0009</td><td>Any 3 digits</td><td>Any future date</td></tr></tbody></table><p>Use these to test: <strong>instant payment</strong> at checkout, <strong>deferred booking</strong> (card saved, charge at T-48), and <strong>successful T-48 charge</strong> without 3DS.</p><h3 id="_3d-secure-3ds-–-authentication-required" tabindex="-1">3D Secure (3DS) – authentication required <a class="header-anchor" href="#_3d-secure-3ds-–-authentication-required" aria-label="Permalink to &quot;3D Secure (3DS) – authentication required&quot;">​</a></h3><p>These cards trigger the <strong>3DS</strong> flow (bank verification step). Use them to test:</p><ul><li>Checkout where the customer must complete 3DS before payment succeeds.</li><li><strong>T-48 charge</strong> that requires 3DS: the student will see the lesson in “Complete payment” / “Incomplete checkouts” and must complete 3DS to finish payment.</li></ul><table tabindex="0"><thead><tr><th>Scenario</th><th>Card number</th><th>Use case</th></tr></thead><tbody><tr><td>3DS required, succeeds</td><td>4000 0000 0000 3220</td><td>Payment succeeds <strong>after</strong> customer completes 3DS.</td></tr><tr><td>3DS required, always</td><td>4000 0027 6000 3184</td><td>Always asks for 3DS (good for testing the full flow).</td></tr><tr><td>Authenticate unless set up</td><td>4000 0025 0000 3155</td><td>Requires 3DS for one-time/on-session; after “set up”, off-session (e.g. T-48) can succeed without 3DS.</td></tr></tbody></table><p>Use <strong>any 3-digit CVC</strong> and <strong>any future expiry</strong> (e.g. 12/34).</p><h3 id="declined-failure-for-error-handling" tabindex="-1">Declined / failure (for error handling) <a class="header-anchor" href="#declined-failure-for-error-handling" aria-label="Permalink to &quot;Declined / failure (for error handling)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Card number</th><th>Result</th></tr></thead><tbody><tr><td>Generic decline</td><td>4000 0000 0000 0002</td><td>Card declined (generic).</td></tr><tr><td>Insufficient funds</td><td>4000 0000 0000 9995</td><td>Decline: insufficient funds.</td></tr><tr><td>3DS required, then decline</td><td>4000 0084 0000 1629</td><td>3DS is required; after authentication, payment is declined.</td></tr><tr><td>Insufficient funds (3DS)</td><td>4000 0082 6000 3178</td><td>Requires 3DS; after authentication, declined (insufficient funds).</td></tr></tbody></table><p><strong>Important:</strong></p><ul><li>Do <strong>not</strong> use real card details in test mode.</li><li>Full list: <a href="https://docs.stripe.com/testing#cards" target="_blank" rel="noreferrer">Stripe Testing – Card numbers</a> and <a href="https://docs.stripe.com/testing#regulatory-cards" target="_blank" rel="noreferrer">Test 3D Secure</a>.</li></ul><hr><h2 id="_4-payment-flows-instant-vs-deferred-and-how-we-show-them" tabindex="-1">4. Payment flows (instant vs deferred) and how we show them <a class="header-anchor" href="#_4-payment-flows-instant-vs-deferred-and-how-we-show-them" aria-label="Permalink to &quot;4. Payment flows (instant vs deferred) and how we show them&quot;">​</a></h2><h3 id="instant-payment-lesson-within-48-hours" tabindex="-1">Instant payment (lesson within 48 hours) <a class="header-anchor" href="#instant-payment-lesson-within-48-hours" aria-label="Permalink to &quot;Instant payment (lesson within 48 hours)&quot;">​</a></h3><ul><li>Student books and pays <strong>immediately</strong> at Stripe Checkout.</li><li>On success, the booking is <strong>confirmed</strong> and all slots are <strong>paid</strong>. No “complete payment” step later.</li></ul><h3 id="deferred-payment-lesson-more-than-48-hours-away" tabindex="-1">Deferred payment (lesson more than 48 hours away) <a class="header-anchor" href="#deferred-payment-lesson-more-than-48-hours-away" aria-label="Permalink to &quot;Deferred payment (lesson more than 48 hours away)&quot;">​</a></h3><ul><li>Student goes to Checkout in <strong>setup</strong> mode: only the <strong>card is saved</strong>, no charge yet.</li><li><strong>48 hours before</strong> each lesson, our system automatically charges the saved card (<strong>T-48 charge</strong>). If that charge <strong>succeeds</strong>, the slot is marked <strong>paid</strong> and the student sees nothing extra.</li><li>If the charge <strong>fails</strong> (e.g. insufficient funds) or <strong>requires 3DS</strong>, the slot stays in a “payment incomplete” state and the student can complete it later (see below).</li></ul><h3 id="incomplete-checkouts-and-complete-payment" tabindex="-1">Incomplete checkouts and “Complete payment” <a class="header-anchor" href="#incomplete-checkouts-and-complete-payment" aria-label="Permalink to &quot;Incomplete checkouts and “Complete payment”&quot;">​</a></h3><ul><li><p><strong>Incomplete checkout (never finished Stripe):</strong><br> Student started checkout but closed the page or cancelled. The booking stays <strong>pending</strong>. On the <strong>Book lesson</strong> page we show an <strong>“Incomplete checkouts”</strong> section: the student can click <strong>“Continue to checkout”</strong> to finish payment for the <strong>same</strong> booking (same lesson, no new search).</p><ul><li>They <strong>cannot</strong> complete this checkout if the <strong>lesson date has already passed</strong>.</li></ul></li><li><p><strong>T-48 charge failed or required 3DS:</strong><br> For <strong>deferred</strong> bookings, when we charge 48 hours before the lesson, the charge might:</p><ul><li><strong>Require 3DS:</strong> we mark the slot as <code>requires_action</code>. The student must complete 3DS (we show a “Complete payment” / 3DS flow in the app).</li><li><strong>Fail</strong> (e.g. decline): we mark the slot as <code>payment_failed</code>. The student can <strong>retry</strong> via the same “Complete payment” flow (we create a new PaymentIntent or use the existing one where supported).</li></ul></li><li><p><strong>Where the student sees this:</strong></p><ul><li><strong>Book lesson</strong> page: list of <strong>“Complete payment”</strong> slots (lessons that need 3DS or retry), and <strong>“Incomplete checkouts”</strong> (pending bookings that never finished Checkout).</li><li><strong>Booking details</strong> (for a specific booking): if that slot needs 3DS or retry, we show a <strong>“Complete payment”</strong> button and a short explanation.</li></ul></li><li><p><strong>When we no longer allow completion:</strong><br> The student <strong>cannot</strong> complete payment (and we hide or disable “Complete payment”) if:</p><ul><li>The <strong>lesson date/time has passed</strong>, or</li><li>The instructor has already marked the lesson <strong>Completed</strong> or <strong>Missed</strong>.</li></ul></li></ul><p>So: incomplete checkouts and 3DS/failed T-48 are explicitly supported; we only block “complete payment” when the lesson is already in the past or finalized by the instructor.</p><hr><h2 id="_5-refunds-when-they-are-allowed-and-when-they-are-blocked" tabindex="-1">5. Refunds: when they are allowed and when they are blocked <a class="header-anchor" href="#_5-refunds-when-they-are-allowed-and-when-they-are-blocked" aria-label="Permalink to &quot;5. Refunds: when they are allowed and when they are blocked&quot;">​</a></h2><h3 id="student-requests-a-refund" tabindex="-1">Student requests a refund <a class="header-anchor" href="#student-requests-a-refund" aria-label="Permalink to &quot;Student requests a refund&quot;">​</a></h3><ul><li>Refund can <strong>only</strong> be requested for a <strong>cancelled</strong> lesson (student or instructor cancelled the slot).</li><li>We <strong>block</strong> a refund request if: <ul><li>The <strong>lesson date/time has already passed</strong> (request must be made before the lesson time).</li><li>The lesson was <strong>never paid</strong> (e.g. deferred booking cancelled before T-48 charge).</li><li>The instructor has <strong>already been paid out</strong> for that slot (no refund after payout).</li><li>The slot is <strong>already refunded</strong> or a refund request is <strong>pending/rejected</strong>.</li></ul></li></ul><p>So: <strong>request refund</strong> only for <strong>cancelled</strong>, <strong>paid</strong>, <strong>not yet paid-out</strong> lessons, and <strong>before</strong> the lesson time.</p><h3 id="admin-approves-or-rejects-a-refund" tabindex="-1">Admin approves or rejects a refund <a class="header-anchor" href="#admin-approves-or-rejects-a-refund" aria-label="Permalink to &quot;Admin approves or rejects a refund&quot;">​</a></h3><ul><li><p>Admin can <strong>approve</strong> a refund request only if:</p><ul><li>The slot is <strong>not</strong> already refunded.</li><li>The instructor has <strong>not</strong> already been paid out for that slot.</li><li>The slot status is <strong>not</strong> <strong>completed</strong> or <strong>missed</strong> (we block approve if the lesson was later marked completed or missed).</li><li>The <strong>lesson date/time has not passed</strong> (we block approve if the lesson is in the past).</li></ul></li><li><p>Admin can <strong>reject</strong> a request with an optional reason (e.g. “Payout already sent”).</p></li></ul><p>We <strong>do not</strong> allow double refunds or refunds after the instructor has been paid out. All these checks are enforced in code and in the admin refund screen (e.g. both Approve and Reject are disabled while one action is in progress to avoid race conditions).</p><hr><h2 id="_6-lesson-completed-and-missed-status" tabindex="-1">6. Lesson “Completed” and “Missed” status <a class="header-anchor" href="#_6-lesson-completed-and-missed-status" aria-label="Permalink to &quot;6. Lesson “Completed” and “Missed” status&quot;">​</a></h2><h3 id="who-can-mark-a-lesson-completed-or-missed" tabindex="-1">Who can mark a lesson completed or missed? <a class="header-anchor" href="#who-can-mark-a-lesson-completed-or-missed" aria-label="Permalink to &quot;Who can mark a lesson completed or missed?&quot;">​</a></h3><ul><li>The <strong>instructor</strong> (or admin) can set a slot to <strong>Completed</strong> or <strong>Missed</strong> from the booking/slot management UI.</li></ul><h3 id="when-can-a-lesson-be-marked-completed" tabindex="-1">When can a lesson be marked “Completed”? <a class="header-anchor" href="#when-can-a-lesson-be-marked-completed" aria-label="Permalink to &quot;When can a lesson be marked “Completed”?&quot;">​</a></h3><ul><li><strong>Only after the lesson end time.</strong><br> The system checks the <strong>slot end time in Switzerland time</strong> (Europe/Zurich). If the current time (in UTC) is <strong>before</strong> that slot end time, the platform <strong>does not allow</strong> marking the lesson as completed.<br> So instructors cannot mark a lesson completed before it has actually ended.</li></ul><h3 id="what-completed-and-missed-imply" tabindex="-1">What “Completed” and “Missed” imply <a class="header-anchor" href="#what-completed-and-missed-imply" aria-label="Permalink to &quot;What “Completed” and “Missed” imply&quot;">​</a></h3><ul><li><strong>Completed:</strong> The lesson took place. For <strong>paid</strong> slots, the slot becomes <strong>eligible for payout</strong> after the configured delay (e.g. 1 minute in current setup), then the next payout job run will send the instructor’s share to their bank (subject to Stripe’s “available” timing).</li><li><strong>Missed:</strong> The lesson did not take place (e.g. student no-show). No refund is issued for “missed” in the normal flow. We <strong>block</strong> refund request/approve for slots marked <strong>missed</strong> (and <strong>completed</strong>) as per <a href="#5-refunds-when-they-are-allowed-and-when-they-are-blocked">§5</a>.</li></ul><hr><h2 id="_7-cancellation-rules" tabindex="-1">7. Cancellation rules <a class="header-anchor" href="#_7-cancellation-rules" aria-label="Permalink to &quot;7. Cancellation rules&quot;">​</a></h2><ul><li><p>A lesson can be <strong>cancelled</strong> only if:</p><ul><li>It is <strong>not</strong> already cancelled, and</li><li>Its status is <strong>not</strong> completed, missed, or refund, and</li><li>The <strong>lesson date has not passed</strong> (cancellation only before the scheduled date).</li></ul></li><li><p>If the student <strong>cancels before</strong> the T-48 charge (e.g. deferred booking, cancelled early), <strong>no charge</strong> is made for that slot and <strong>no refund</strong> is relevant (we do not show “Request refund” for unpaid slots).</p></li></ul><hr><h2 id="_8-edge-cases-we-handle-summary" tabindex="-1">8. Edge cases we handle (summary) <a class="header-anchor" href="#_8-edge-cases-we-handle-summary" aria-label="Permalink to &quot;8. Edge cases we handle (summary)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>What we do</th></tr></thead><tbody><tr><td><strong>Incomplete checkout</strong></td><td>Student can resume from “Incomplete checkouts” with “Continue to checkout” for the same booking; blocked if lesson date has passed.</td></tr><tr><td><strong>T-48 requires 3DS</strong></td><td>Slot marked <code>requires_action</code>; student sees “Complete payment” and can complete 3DS; blocked if lesson date passed or instructor marked completed/missed.</td></tr><tr><td><strong>T-48 charge failed</strong></td><td>Slot marked <code>payment_failed</code>; student can retry via “Complete payment”; same blocks as above.</td></tr><tr><td><strong>Mark completed before end time</strong></td><td>Rejected: “Cannot mark this slot as completed before its end time.” (Switzerland timezone).</td></tr><tr><td><strong>Refund after payout</strong></td><td>Request/approve blocked: instructor already paid out.</td></tr><tr><td><strong>Refund for missed/completed</strong></td><td>Approve blocked: lesson was marked missed or completed.</td></tr><tr><td><strong>Refund after lesson date passed</strong></td><td>Request and approve blocked when lesson date/time has passed.</td></tr><tr><td><strong>Double payout</strong></td><td>Payout job uses an atomic “claim” so the same slot is never paid out twice.</td></tr><tr><td><strong>Deferred booking cancelled before T-48</strong></td><td>No charge; no refund; T-48 job skips cancelled slots.</td></tr><tr><td><strong>Currency on Checkout</strong></td><td>Only CHF; Adaptive Pricing disabled in code and can be turned off in Stripe Dashboard if needed.</td></tr></tbody></table><hr><h2 id="_9-stripe-webhook-production" tabindex="-1">9. Stripe webhook (production) <a class="header-anchor" href="#_9-stripe-webhook-production" aria-label="Permalink to &quot;9. Stripe webhook (production)&quot;">​</a></h2><ul><li>So that Stripe can send payment and account events to your server, configure the webhook in the Stripe Dashboard: <ul><li><strong>Endpoint URL:</strong> <code>https://dsp-cloud.onrender.com/webhooks/stripe</code></li><li>Use the <strong>signing secret</strong> from that endpoint in your server environment as <code>STRIPE_WEBHOOK_SECRET</code>.</li></ul></li><li>Events we use: <code>checkout.session.completed</code>, <code>payment_intent.succeeded</code>, <code>account.updated</code>, <code>account.application.deauthorized</code>, <code>charge.dispute.created</code>, <code>charge.dispute.closed</code>, <code>payout.failed</code>, <code>payout.paid</code>.</li></ul><hr><h2 id="_10-configuration-summary-for-your-reference" tabindex="-1">10. Configuration summary (for your reference) <a class="header-anchor" href="#_10-configuration-summary-for-your-reference" aria-label="Permalink to &quot;10. Configuration summary (for your reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value / behaviour</th></tr></thead><tbody><tr><td><strong>Currency</strong></td><td>CHF only (no multi-currency for customers).</td></tr><tr><td><strong>Slot timezone</strong></td><td>Europe/Zurich (Switzerland).</td></tr><tr><td><strong>Payout delay after “completed”</strong></td><td>1 minute (configurable; can be set to 3 days for production).</td></tr><tr><td><strong>Payout job interval</strong></td><td>Every 3 minutes.</td></tr><tr><td><strong>Stripe funds “available” (CH)</strong></td><td>First payout: ~7 days; then ~3 business days.</td></tr><tr><td><strong>Webhook URL</strong></td><td><code>https://dsp-cloud.onrender.com/webhooks/stripe</code>.</td></tr></tbody></table><hr><p>If you need to test a specific flow (e.g. 3DS, decline, refund after payout blocked), use the test cards in <a href="#3-stripe-test-cards-sandbox">§3</a> and the rules above. For full technical details, see the internal docs (e.g. <code>BUSINESS_RULES_CANCEL_REFUND_PAYMENT_PAYOUT.md</code>, <code>BACKEND_STRIPE_AND_PAYMENT_GUIDE.md</code>).</p>',68)])])}const g=t(r,[["render",a]]);export{p as __pageData,g as default};
